export const WORLD=3900,FLOOR=440;
export const gates=[600,1300,2000,2700,3400],gaps=[{x:940,w:95},{x:2250,w:105}];
export const platforms=[{x:260,y:350,w:135,h:22},{x:440,y:285,w:105,h:22},{x:780,y:345,w:95,h:22},{x:1080,y:360,w:105,h:22},{x:1460,y:355,w:120,h:22},{x:1640,y:285,w:130,h:22},{x:1860,y:355,w:95,h:22},{x:2100,y:340,w:95,h:22},{x:2390,y:350,w:120,h:22},{x:2850,y:350,w:130,h:22},{x:3040,y:280,w:120,h:22},{x:3230,y:355,w:100,h:22}];
export function newGame(){const coins=[];for(let x=180;x<3660;x+=65)if(!gaps.some(g=>x>g.x-15&&x<g.x+g.w+15)&&!gates.some(g=>Math.abs(x-g)<65))coins.push({x,y:FLOOR-40,taken:false});platforms.forEach(p=>{for(let x=p.x+25;x<p.x+p.w;x+=42)coins.push({x,y:p.y-34,taken:false});});return {player:{x:70,y:FLOOR-62,w:44,h:62,vx:0,vy:0,ground:true,face:1,windup:0,jumpAge:1,landAge:1,runPhase:0},coins,count:0,solved:0,checkpoint:70,hearts:3,time:0,invincible:0,jumpHeld:false,coyote:.1,jumpBuffer:0,finished:false,enemies:[{x:800,origin:800,range:40,w:40,h:30},{x:1510,origin:1510,range:75,w:40,h:30},{x:2460,origin:2460,range:68,w:40,h:30},{x:3130,origin:3130,range:62,w:40,h:30}],particles:[]};}
export function overlap(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y;}
export function rescue(s){const p=s.player;if(--s.hearts===0)s.hearts=3;p.x=s.checkpoint;p.y=FLOOR-p.h;p.vx=0;p.vy=0;p.ground=true;p.windup=0;p.landAge=1;s.invincible=1.6;s.coyote=.1;s.jumpBuffer=0;return {type:'rescue'};}
export function unlock(s){if(s.solved>=5)return;s.checkpoint=gates[s.solved]+70;s.solved++;s.player.x=s.checkpoint;s.player.y=FLOOR-s.player.h;s.player.vx=0;s.player.vy=0;s.player.ground=true;s.player.windup=0;s.player.landAge=1;s.invincible=1.2;}
export function update(s,input,dt){dt=Math.min(.035,Math.max(0,dt));const events=[],p=s.player,wasGround=p.ground;p.jumpAge+=dt;p.landAge+=dt;if(p.ground&&p.vx)p.runPhase+=Math.abs(p.vx)*dt/36;s.time+=dt;s.invincible=Math.max(0,s.invincible-dt);s.coyote=p.ground?.11:Math.max(0,s.coyote-dt);if(input.jump&&!s.jumpHeld)s.jumpBuffer=.13;s.jumpHeld=!!input.jump;s.jumpBuffer=Math.max(0,s.jumpBuffer-dt);const dir=(input.right?1:0)-(input.left?1:0);p.vx=dir*250;if(dir)p.face=dir;if(p.windup>0){p.windup=Math.max(0,p.windup-dt);if(p.windup===0){p.vy=-590;p.ground=false;p.jumpAge=0;s.coyote=0;events.push({type:'jump'});}}else if(s.jumpBuffer>0&&s.coyote>0){p.windup=.07;s.jumpBuffer=0;events.push({type:'crouch'});}p.vy+=1500*dt;p.x=Math.max(0,Math.min(WORLD-p.w,p.x+p.vx*dt));if(s.solved<5&&p.x+p.w>gates[s.solved]-16){p.x=gates[s.solved]-16-p.w;if(dir>0)events.push({type:'gate',index:s.solved});}const oldBottom=p.y+p.h;p.y+=p.vy*dt;p.ground=false;const onGround=!gaps.some(g=>p.x+p.w*.65>g.x&&p.x+p.w*.35<g.x+g.w);const surfaces=onGround?[...platforms,{x:0,y:FLOOR,w:WORLD,h:50}]:platforms;let landing=null;for(const z of surfaces)if(p.vy>=0&&oldBottom<=z.y+2&&p.y+p.h>=z.y&&p.x+p.w>z.x&&p.x<z.x+z.w&&(!landing||z.y<landing.y))landing=z;if(landing){if(!wasGround&&p.vy>140){p.landAge=0;events.push({type:'land'});}p.y=landing.y-p.h;p.vy=0;p.ground=true;}if(p.y>570){events.push(rescue(s));return events;}for(const c of s.coins)if(!c.taken&&overlap(p,{x:c.x-12,y:c.y-14,w:24,h:28})){c.taken=true;s.count++;s.particles.push({x:c.x,y:c.y,age:0,text:'+1'});events.push({type:'coin'});}for(const e of s.enemies){e.x=e.origin+Math.sin(s.time*1.5)*e.range;e.y=FLOOR-e.h;if(overlap(p,e)&&s.invincible===0){if(p.vy>0&&oldBottom<e.y+16){e.origin=-1000;e.x=-1000;p.vy=-390;s.count+=3;s.particles.push({x:p.x,y:p.y,age:0,text:'+3'});events.push({type:'stomp'});}else{events.push(rescue(s));break;}}}s.particles=s.particles.filter(a=>(a.age+=dt)<1);if(s.solved===5&&p.x>3690){s.finished=true;events.push({type:'finish'});}return events;}

